components.css:
.ds-navigation { display:flex; align-items:center; justify-content:space-between; gap:24px; min-height:82px; padding:0 28px; border-bottom:1px solid rgb(0 0 0 / 10%); background:var(--color-muni-paper); color:var(--color-muni-ink); font-family:var(--font-sans); }
.ds-brand { display:flex; flex-direction:column; color:inherit; text-decoration:none; }
.ds-brand strong { font-size:19px; font-weight:600; line-height:1.15; letter-spacing:-0.04em; }
.ds-brand small { margin-top:2px; color:var(--color-muni-muted); font-size:10px; font-weight:500; letter-spacing:0.12em; text-transform:uppercase; }
.ds-links { display:flex; gap:28px; font-size:13px; font-weight:500; }
.ds-links a { color:inherit; text-decoration:none; }
.ds-links a:hover { color:var(--color-muni-red-dark); }
.ds-nav-action { display:inline-flex; align-items:center; min-height:44px; padding:0 20px; border-radius:9999px; background:var(--color-muni-red-dark); color:#fff; font-size:13px; font-weight:600; text-decoration:none; }
.ds-nav-action:hover { background:var(--color-red-800); }
.ds-navigation a:focus-visible { outline:2px solid var(--color-muni-red); outline-offset:3px; }
@media (max-width:767px) { .ds-navigation { padding:0 16px; } .ds-links,.ds-nav-action { display:none; } }

.ds-button-primary { display:inline-flex; align-items:center; justify-content:center; min-height:48px; padding:0 24px; border:0; border-radius:9999px; background:var(--color-muni-red-dark); color:var(--color-muni-paper); font:600 14px/1.2 var(--font-sans); cursor:pointer; transition:background-color 150ms cubic-bezier(0.4,0,0.2,1),transform 150ms cubic-bezier(0.4,0,0.2,1); }
.ds-button-primary:hover { transform:translateY(-2px); background:var(--color-red-800); }
.ds-button-primary:focus-visible { outline:2px solid var(--color-muni-red); outline-offset:3px; }
@media (prefers-reduced-motion:reduce) { .ds-button-primary { transition:none; } }

.ds-button-secondary { display:inline-flex; align-items:center; justify-content:center; min-height:48px; padding:0 24px; border:1px solid rgb(0 0 0 / 20%); border-radius:9999px; background:#fff; color:var(--color-muni-ink); font:500 14px/1.2 var(--font-sans); cursor:pointer; }
.ds-button-secondary:hover { border-color:rgb(0 0 0 / 40%); background:rgb(0 0 0 / 5%); }
.ds-button-secondary:focus-visible { outline:2px solid var(--color-muni-red); outline-offset:3px; }

.ds-filters { display:flex; flex-wrap:wrap; gap:8px; font-family:var(--font-sans); }
.ds-filter { display:inline-flex; align-items:center; min-height:36px; padding:0 16px; border:1px solid rgb(0 0 0 / 15%); border-radius:9999px; background:#fff; color:var(--color-muni-ink); font-size:13px; font-weight:500; text-decoration:none; }
.ds-filter:hover { border-color:var(--color-muni-red); color:var(--color-muni-red-dark); }
.ds-filter:focus-visible { outline:2px solid var(--color-muni-red); outline-offset:3px; }
.ds-filter-selected,.ds-filter-selected:hover { border-color:var(--color-muni-ink); background:var(--color-muni-ink); color:#fff; }

.ds-featured { max-width:432px; padding:20px; border-radius:16px; background:#8F2632; color:var(--color-muni-paper); box-shadow:0 18px 50px -22px rgba(0,0,0,.5); font-family:var(--font-sans); }

.ds-featured h2 { font-size:24px; font-weight:600; line-height:1.2; letter-spacing:-.035em; }
.ds-featured-meta { margin-top:8px; color:rgb(255 255 255 / 85%); font-size:14px; line-height:1.5; }
.ds-featured a { display:inline-flex; margin-top:16px; color:#fff; font-size:14px; font-weight:600; text-decoration:underline; text-decoration-color:rgb(255 255 255 / 50%); text-underline-offset:4px; }
.ds-featured a:hover { text-decoration-color:#fff; }
.ds-featured a:focus-visible { outline:2px solid var(--color-muni-red); outline-offset:3px; }

.ds-register-row { display:grid; grid-template-columns:92px minmax(0,1.45fr) minmax(160px,.85fr) 128px 40px; align-items:center; gap:24px; padding:28px 0; border-bottom:1px solid rgb(0 0 0 / 10%); color:var(--color-muni-ink); font-family:var(--font-sans); }
.ds-row-date { display:flex; flex-direction:column; font-variant-numeric:tabular-nums; }
.ds-row-date strong { font-size:30px; font-weight:600; line-height:1; letter-spacing:-.04em; }
.ds-row-date span { margin-top:4px; color:var(--color-muni-red-dark); font-size:12px; font-weight:600; letter-spacing:.08em; }
.ds-row-meta { margin-bottom:8px; color:var(--color-muni-muted); font-size:11px; font-weight:600; letter-spacing:.11em; }
.ds-row-main h3 { font-size:18px; font-weight:600; line-height:1.375; letter-spacing:-.025em; }
.ds-row-description,.ds-row-place { color:var(--color-muni-muted); font-size:14px; line-height:1.6; }
.ds-row-description { margin-top:6px; }
.ds-row-state { width:fit-content; padding:6px 12px; border-radius:9999px; background:var(--color-red-50); color:var(--color-red-800); font-size:12px; font-weight:600; }
.ds-row-action { display:grid; width:40px; height:40px; place-items:center; border:1px solid rgb(0 0 0 / 15%); border-radius:9999px; color:var(--color-muni-ink); text-decoration:none; }
.ds-row-action:hover { border-color:var(--color-muni-red); background:var(--color-red-800); color:#fff; }
@media (max-width:639px) { .ds-register-row { grid-template-columns:1fr auto; gap:12px 16px; padding:24px 0; } .ds-row-date { flex-direction:row; gap:8px; } .ds-row-main,.ds-row-place { grid-column:1/-1; } .ds-row-action { display:none; } }

.ds-field { display:block; color:var(--color-muni-ink); font-family:var(--font-sans); }
.ds-field span { display:block; margin-bottom:8px; font-size:14px; font-weight:600; }
.ds-field input { display:block; width:100%; padding:13.6px 16px; border:1px solid rgb(25 25 25 / 18%); border-radius:12px; background:#fff; color:var(--color-muni-ink); font:400 15px/1.5 var(--font-sans); transition:border-color 160ms ease,box-shadow 160ms ease; }
.ds-field input::placeholder { color:var(--color-muni-muted); opacity:1; }
.ds-field input:hover { border-color:rgb(25 25 25 / 38%); }
.ds-field input:focus-visible { border-color:var(--color-muni-red); outline:none; box-shadow:0 0 0 3px rgb(230 57 70 / 16%); }
.ds-field small { display:block; margin-top:6px; color:var(--color-muni-muted); font-size:12px; line-height:1.5; }

.ds-delete { padding:32px 0; border-block:1px solid #f5a4aa; color:var(--color-muni-ink); font-family:var(--font-sans); }
.ds-delete h2 { font-size:32px; font-weight:600; line-height:1.2; letter-spacing:-.04em; }
.ds-delete p { margin-top:12px; color:var(--color-muni-muted); font-size:14px; line-height:1.6; }
.ds-delete-actions { display:flex; flex-wrap:wrap; justify-content:flex-end; gap:12px; margin-top:24px; }
.ds-keep,.ds-delete-button { min-height:48px; padding:0 24px; border-radius:9999px; font:600 14px/1.2 var(--font-sans); cursor:pointer; }
.ds-keep { border:1px solid rgb(0 0 0 / 20%); background:#fff; color:var(--color-muni-ink); }
.ds-delete-button { border:0; background:var(--color-muni-red-dark); color:#fff; }
.ds-delete-button:hover { background:var(--color-red-800); }
.ds-delete-actions button:focus-visible { outline:2px solid var(--color-muni-red); outline-offset:3px; }
@media (max-width:639px) { .ds-delete-actions { flex-direction:column-reverse; } .ds-delete-actions button { width:100%; } }
